{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "The mean share of a frame each label covers, over the walk's frames.",
  "title": "Mean share of a frame (%)",
  "transform": [
    {
      "fold": [
        "curb cut_pct",
        "curb ramp_pct",
        "wheelchair ramp_pct",
        "tactile paving_pct",
        "pole_pct",
        "bollard_pct",
        "construction barrier_pct",
        "traffic cone_pct",
        "person_pct"
      ],
      "as": [
        "column",
        "share"
      ]
    },
    {
      "calculate": "replace(datum.column, '_pct', '')",
      "as": "label"
    },
    {
      "aggregate": [
        {
          "op": "mean",
          "field": "share",
          "as": "mean_share"
        }
      ],
      "groupby": [
        "label"
      ]
    }
  ],
  "mark": "bar",
  "encoding": {
    "y": {
      "field": "label",
      "type": "nominal",
      "sort": "-x",
      "title": null
    },
    "x": {
      "field": "mean_share",
      "type": "quantitative",
      "title": "Mean share of a frame (%)"
    }
  }
}

{
  "map": {
    "layerRefs": [
      {
